import manifest from "./manifest.json";
import type { Scene } from "../config";

/**
 * Typed access to `src/voice/manifest.json`, which is generated by
 * `npm run voiceover` (see scripts/generate-voiceover.mjs).
 *
 * The manifest is the only place that knows how long the narration is, so the
 * timeline can stretch each scene to fit the audio instead of guessing.
 */

export type VoiceWord = {
  text: string;
  /** Seconds from the start of the clip. */
  start: number;
  end: number;
};

export type VoiceScene = {
  index: number;
  /** Path relative to `public/`, for `staticFile()`. */
  file: string;
  text: string;
  hash: string;
  durationInSeconds: number;
  words: VoiceWord[];
};

export type VoiceManifest = {
  provider: string;
  voice: string;
  rate: string;
  pitch: string;
  outputFormat: string;
  generatedAt: string;
  totalSeconds: number;
  scenes: VoiceScene[];
};

export const VOICE_MANIFEST = manifest as VoiceManifest;

const BY_INDEX = new Map(VOICE_MANIFEST.scenes.map((scene) => [scene.index, scene]));

/** Narration clip for a scene, or undefined when the scene has no audio. */
export const getVoiceScene = (index: number): VoiceScene | undefined =>
  BY_INDEX.get(index);

/**
 * End of the last spoken word in seconds. Scenes are sized from this (plus a
 * short tail) so the trailing silence of the clip never pads the video.
 */
export const getSpeechEndSeconds = (index: number): number | undefined => {
  const scene = BY_INDEX.get(index);
  if (!scene) {
    return undefined;
  }
  const last = scene.words[scene.words.length - 1];
  return last ? last.end : scene.durationInSeconds;
};

/** True while a word is actually being spoken (pauses close the mouth). */
export const isWordActiveAt = (index: number, secondsIntoScene: number): boolean => {
  const scene = BY_INDEX.get(index);
  if (!scene) {
    return false;
  }
  for (const word of scene.words) {
    if (secondsIntoScene >= word.start - 0.02 && secondsIntoScene <= word.end + 0.06) {
      return true;
    }
  }
  return false;
};

const REVEAL_LEAD_SECONDS = 0.1;
const MIN_REVEAL_SPACING_SECONDS = 0.3;
const FALLBACK_FIRST_REVEAL_SECONDS = 0.5;
const FALLBACK_REVEAL_STEP_SECONDS = 0.4;

const tokenize = (text: string): string[] =>
  text
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter((token) => token.length > 0);

const firstToken = (text: string): string => tokenize(text)[0] ?? "";

export type ItemReveal = {
  /** Seconds from the start of the scene. */
  at: number;
  /** True when the item's first word was found in the narration. */
  matched: boolean;
};

/**
 * Resolves when each `points` item should appear.
 *
 * Matches the item's first word against the narration word timings, so a new
 * bullet (and its pose change) lands exactly when the voice says it. Items that
 * cannot be matched fall back to a fixed stagger.
 */
export const getItemReveals = (
  index: number,
  items: readonly string[],
): ItemReveal[] => {
  const words = BY_INDEX.get(index)?.words ?? [];
  let cursor = 0;
  let previous = -Infinity;

  return items.map((item, itemIndex) => {
    const fallback =
      FALLBACK_FIRST_REVEAL_SECONDS + itemIndex * FALLBACK_REVEAL_STEP_SECONDS;
    const target = firstToken(item);

    let matchedIndex = -1;
    if (target.length > 0) {
      for (let i = cursor; i < words.length; i++) {
        if (tokenize(words[i].text)[0] === target) {
          matchedIndex = i;
          break;
        }
      }
    }

    const matched = matchedIndex >= 0;
    let at = matched ? words[matchedIndex].start - REVEAL_LEAD_SECONDS : fallback;
    if (matched) {
      cursor = matchedIndex + 1;
    }

    // Never reveal two items on top of each other, never before the scene is
    // visible, and round to the millisecond for a stable manifest-free result.
    at = Math.max(at, 0.15, previous + MIN_REVEAL_SPACING_SECONDS);
    at = Math.round(at * 1000) / 1000;
    previous = at;

    return { at, matched };
  });
};

/** Convenience wrapper when only the seconds are needed (scenes / timeline). */
export const getItemRevealSeconds = (
  index: number,
  items: readonly string[],
): number[] => getItemReveals(index, items).map((reveal) => reveal.at);

/**
 * Fails loudly when `script.json` was edited without regenerating the audio,
 * which would otherwise silently play the wrong (or no) narration.
 */
export const assertVoiceoverMatchesScript = (scenes: readonly Scene[]): void => {
  const problems: string[] = [];

  scenes.forEach((scene, index) => {
    const voice = BY_INDEX.get(index);
    const label = `scene ${index + 1}`;

    if (scene.voiceover === undefined) {
      if (voice) {
        problems.push(`${label}: audio exists but "voiceover" text was removed`);
      }
      return;
    }

    if (!voice) {
      problems.push(`${label}: has "voiceover" text but no generated audio`);
      return;
    }

    if (voice.text !== scene.voiceover.trim()) {
      problems.push(`${label}: narration text changed since the audio was generated`);
    }
  });

  if (problems.length > 0) {
    throw new Error(
      `Voiceover is out of date:\n- ${problems.join("\n- ")}\n` +
        `Run "npm run voiceover" (add -- --force to rebuild every clip).`,
    );
  }
};
